class _AdminItemsListBody extends StatelessWidget {
  const _AdminItemsListBody({
    required this.items,
    required this.initialLoading,
    required this.loadingMore,
    required this.hasMore,
    required this.error,
    required this.onRetry,
    required this.onItemTap,
    required this.selectedCodes,
    required this.onItemSelect,
  });

  final List<SupplierItem> items;
  final bool initialLoading;
  final bool loadingMore;
  final bool hasMore;
  final Object? error;
  final VoidCallback onRetry;
  final AdminItemTapHandler? onItemTap;
  final Set<String> selectedCodes;
  final ValueChanged<SupplierItem>? onItemSelect;

  @override
  Widget build(BuildContext context) {
    if (initialLoading) {
      return SizedBox(
        height: MediaQuery.sizeOf(context).height * 0.48,
        child: const Center(child: AppLoadingIndicator()),
      );
    }
    if (error != null && items.isEmpty) {
      return _ItemListNotice(
        text: context.l10n.adminText('item.loading_failed'),
        actionText: context.l10n.adminText('item.retry'),
        onAction: onRetry,
      );
    }
    return _AdminItemsList(
      items: items,
      loadingMore: loadingMore,
      hasMore: hasMore,
      pageError: error,
      onRetry: onRetry,
      onItemTap: onItemTap,
      selectedCodes: selectedCodes,
      onItemSelect: onItemSelect,
    );
  }
}

class _AdminItemsList extends StatelessWidget {
  const _AdminItemsList({
    required this.items,
    required this.loadingMore,
    required this.hasMore,
    required this.pageError,
    required this.onRetry,
    required this.onItemTap,
    required this.selectedCodes,
    required this.onItemSelect,
  });

  final List<SupplierItem> items;
  final bool loadingMore;
  final bool hasMore;
  final Object? pageError;
  final VoidCallback onRetry;
  final AdminItemTapHandler? onItemTap;
  final Set<String> selectedCodes;
  final ValueChanged<SupplierItem>? onItemSelect;

  @override
  Widget build(BuildContext context) {
    if (items.isEmpty) {
      return _ItemListNotice(
        text: context.l10n.adminText('item.empty'),
      );
    }
    final scheme = Theme.of(context).colorScheme;
    return Column(
      children: [
        M3SegmentSpacedColumn(
          padding: EdgeInsets.zero,
          children: [
            for (var index = 0; index < items.length; index++)
              _AdminItemRow(
                slot: M3SegmentedListGeometry.standaloneListSlotForIndex(
                  index,
                  items.length,
                ),
                item: items[index],
                selected: selectedCodes.contains(items[index].code),
                onSelect: onItemSelect == null
                    ? null
                    : () => onItemSelect!(items[index]),
                onTap:
                    onItemTap == null ? null : () => onItemTap!(items[index]),
              ),
          ],
        ),
        if (loadingMore)
          const Padding(
            padding: EdgeInsets.all(14),
            child: AppLoadingIndicator(size: 48, glyphSize: 28),
          )
        else if (pageError != null)
          Padding(
            padding: const EdgeInsets.all(12),
            child: OutlinedButton.icon(
              onPressed: onRetry,
              icon: const Icon(Icons.refresh_rounded),
              label: Text(context.l10n.adminText('item.load_more')),
            ),
          )
        else if (hasMore)
          Padding(
            padding: const EdgeInsets.all(12),
            child: Text(
              context.l10n.adminText('item.scroll_load_more'),
              style: Theme.of(
                context,
              ).textTheme.bodySmall?.copyWith(color: scheme.onSurfaceVariant),
            ),
          ),
      ],
    );
  }
}

class _AdminItemRow extends StatelessWidget {
  const _AdminItemRow({
    required this.slot,
    required this.item,
    required this.selected,
    this.onTap,
    this.onSelect,
  });

  final M3SegmentVerticalSlot slot;
  final SupplierItem item;
  final bool selected;
  final VoidCallback? onTap;
  final VoidCallback? onSelect;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final title = item.name.trim().isEmpty ? item.code : item.name;
    final subtitle = <String>[
      if (item.code.trim().isNotEmpty) item.code.trim(),
      if (item.uom.trim().isNotEmpty) item.uom.trim(),
      if (item.itemGroup.trim().isNotEmpty) item.itemGroup.trim(),
    ].join(' • ');

    return AdminSummaryCard(
      slot: slot,
      cornerRadius: M3SegmentedListGeometry.cornerRadiusForSlot(slot),
      backgroundColor:
          selected ? scheme.secondaryContainer : scheme.surfaceContainerLowest,
      fixedHeight: 61,
      padding: const EdgeInsetsDirectional.fromSTEB(14, 8, 10, 8),
      value: '',
      onTap: onTap,
      onLongPress: onSelect,
      showChevron: onTap != null,
      leading: Semantics(
        selected: selected,
        button: onSelect != null,
        label: title,
        child: InkWell(
          key: ValueKey('admin-item-select-${item.code}'),
          onTap: onSelect,
          borderRadius: BorderRadius.circular(8),
          child: SizedBox.square(
            dimension: 30,
            child: DecoratedBox(
              decoration: BoxDecoration(
                color: selected ? scheme.primary : scheme.secondaryContainer,
                borderRadius: BorderRadius.circular(8),
              ),
              child: Icon(
                selected ? Icons.check_rounded : Icons.inventory_2_rounded,
                size: 16,
                color:
                    selected ? scheme.onPrimary : scheme.onSecondaryContainer,
              ),
            ),
          ),
        ),
      ),
      title: title,
      subtitle: subtitle,
      titleMaxLines: 1,
      subtitleMaxLines: 1,
      titleStyle: Theme.of(
        context,
      ).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w700),
      subtitleStyle: Theme.of(context).textTheme.bodySmall?.copyWith(
            color: scheme.onSurfaceVariant,
            height: 1.05,
          ),
    );
  }
}
